// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

interface IOptionsMarket {
    function resolveMarket(uint256 battleId, uint256 finalRed, uint256 finalBlue) external;
}

/**
 * @title HuntingGrounds
 * @dev The core combat engine for Dreadnaughties. 
 * Implements the N-round Polya Urn state space drawing to resolve attacks on the Open Sea.
 */
contract HuntingGrounds is ReentrancyGuard, Ownable {

    struct Urn {
        uint256 redBalls;   // Alpha (Guns)
        uint256 blueBalls;  // Beta (Protection/Defense)
    }

    struct BattleRecord {
        address attacker;
        address defender;
        uint256 initialRed;
        uint256 initialBlue;
        uint256 finalRed;
        uint256 finalBlue;
        uint256 roundsFought;
        bool attackerWon;
    }

    // Number of draws required to resolve a battle
    uint256 public constant BATTLE_ROUNDS = 5;

    // Threshold of Red Balls needed at the end of the Urn draw for the Attacker to win
    // In a 5 round battle, >= 3 red balls drawn means victory.
    uint256 public constant WIN_THRESHOLD_RED_DRAWN = 3; 

    mapping(uint256 => BattleRecord) public battles;
    uint256 public battleCounter;
    address public optionsMarketAddress;

    event BattleInitiated(uint256 indexed battleId, address indexed attacker, address indexed defender);
    event BattleResolved(uint256 indexed battleId, bool attackerWon, uint256 finalRed, uint256 finalBlue);

    constructor() Ownable(msg.sender) {}

    function setOptionsMarket(address _optionsMarket) external onlyOwner {
        optionsMarketAddress = _optionsMarket;
    }

    /**
     * @notice Initiates a battle using a pseudo-random Polya Urn simulation.
     * @dev In a production environment, this MUST be connected to Chainlink VRF. 
     * For the MVP, we use block parameters to simulate VRF callback synchronously,
     * but we remove the arbitrary _strikePrice vulnerability.
     *
     * @param _attackerRed Attacker's Alpha stat
     * @param _defenderBlue Defender's Beta stat
     * @param _defender Address of the Open Sea target
     * @param _defenderYield The current accumulated yield of the target (Mocked for MVP)
     */
    function executeAttack(
        uint256 _attackerRed, 
        uint256 _defenderBlue, 
        address _defender, 
        uint256 _defenderYield
    ) external payable nonReentrant {
        // Attacker must send a stake (The Premium)
        require(msg.value > 0, "Must stake DREAD (ETH for MVP) to attack");

        // Initialize the Urn
        Urn memory currentUrn = Urn({
            redBalls: _attackerRed,
            blueBalls: _defenderBlue
        });

        require(currentUrn.redBalls + currentUrn.blueBalls > 0, "Empty Urn");

        battleCounter++;
        uint256 currentBattleId = battleCounter;

        emit BattleInitiated(currentBattleId, msg.sender, _defender);

        uint256 redDrawn = 0;
        uint256 blueDrawn = 0;

        // Simulate N rounds of the Polya Urn
        for (uint256 i = 0; i < BATTLE_ROUNDS; i++) {
            uint256 totalBalls = currentUrn.redBalls + currentUrn.blueBalls;

            // SECURITY NOTE: This is a placeholder for Chainlink VRF in production.
            // DO NOT USE block parameters for randomness in production.
            uint256 randomDraw = uint256(keccak256(abi.encodePacked(block.timestamp, blockhash(block.number - 1), msg.sender, i))) % totalBalls;

            if (randomDraw < currentUrn.redBalls) {
                currentUrn.redBalls += 1;
                redDrawn += 1;
            } else {
                currentUrn.blueBalls += 1;
                blueDrawn += 1;
            }
        }

        // Determine Outcome based on Contract Rules (NOT user input)
        bool isVictory = redDrawn >= WIN_THRESHOLD_RED_DRAWN;

        battles[currentBattleId] = BattleRecord({
            attacker: msg.sender,
            defender: _defender,
            initialRed: _attackerRed,
            initialBlue: _defenderBlue,
            finalRed: currentUrn.redBalls,
            finalBlue: currentUrn.blueBalls,
            roundsFought: BATTLE_ROUNDS,
            attackerWon: isVictory
        });

        // 5% of the initial stake is ALWAYS burned, even on victory, to ensure strict deflation.
        uint256 baseBurnFee = (msg.value * 5) / 100;

        if (isVictory) {
            // THE ATTACKER'S REWARD
            uint256 payoutRatio = (redDrawn * 100) / BATTLE_ROUNDS; // Percentage
            uint256 payout = (_defenderYield * payoutRatio) / 100;

            uint256 attackerReturn = (msg.value - baseBurnFee) + payout;

            // Use call instead of transfer for reentrancy safety & gas limits
            (bool success, ) = payable(msg.sender).call{value: attackerReturn}("");
            require(success, "Transfer failed"); 

        } else {
            // THE DEFENDER'S REWARD
            uint256 remainingStake = msg.value - baseBurnFee;
            uint256 rewardRatio = (blueDrawn * 100) / BATTLE_ROUNDS; // Percentage
            uint256 reward = (remainingStake * rewardRatio) / 100;

            if (reward > 0) {
                (bool success, ) = payable(_defender).call{value: reward}("");
                require(success, "Transfer failed");
            }
        }

        if (optionsMarketAddress != address(0)) {
            IOptionsMarket(optionsMarketAddress).resolveMarket(currentBattleId, currentUrn.redBalls, currentUrn.blueBalls);
        }

        emit BattleResolved(currentBattleId, isVictory, currentUrn.redBalls, currentUrn.blueBalls);
    }
}

contracts/OptionsMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title OptionsMarket
 * @dev Derivative market for Dreadnaughties battles.
 * Users can lock DREAD tokens to mint "Red Heavy" or "Blue Heavy" Arrow-Debreu tokens
 * based on the expected outcome of the final 5-Round Polya Urn state space.
 */
contract OptionsMarket is ERC1155, Ownable, ReentrancyGuard {

    // Mapping: BattleID => (Option Type => Total Minted)
    // Option Type 0 = Red > 5 (Aggressive Result)
    // Option Type 1 = Blue >= 5 (Defensive Result)
    mapping(uint256 => mapping(uint256 => uint256)) public marketSize;
    mapping(uint256 => bool) public marketResolved;
    mapping(uint256 => uint256) public winningOptionId;

    // A mock DREAD ERC20 interface would go here
    // IERC20 public dreadToken;

    // Address of the authorized HuntingGrounds contract
    address public huntingGroundsAddress;

    event OptionsMinted(address indexed buyer, uint256 battleId, uint256 optionId, uint256 amount);
    event OptionsExercised(address indexed holder, uint256 battleId, uint256 payout);
    event HuntingGroundsSet(address indexed newAddress);

    constructor() ERC1155("https://api.dreadnaughties.com/options/{id}.json") Ownable(msg.sender) {}

    modifier onlyHuntingGrounds() {
        require(msg.sender == huntingGroundsAddress, "Caller is not HuntingGrounds");
        _;
    }

    function setHuntingGrounds(address _huntingGrounds) external onlyOwner {
        huntingGroundsAddress = _huntingGrounds;
        emit HuntingGroundsSet(_huntingGrounds);
    }

    /**
     * @notice Generates a unique Token ID for an option on a specific battle.
     * Combines battleId and optionType to ensure globally unique ERC-1155 tokens.
     */
    function getOptionId(uint256 battleId, uint256 optionType) public pure returns (uint256) {
        return (battleId << 128) | optionType;
    }

    /**
     * @notice Mint an Arrow-Debreu token for a specific battle.
     * @param battleId The ID from HuntingGrounds.sol
     * @param optionType 0 (Red Heavy) or 1 (Blue Heavy)
     * @param amount The number of options to mint
     */
    function mintOption(uint256 battleId, uint256 optionType, uint256 amount) external payable nonReentrant {
        require(!marketResolved[battleId], "Market already resolved");
        require(optionType == 0 || optionType == 1, "Invalid option type");

        // REQUIREMENT: Must lock DREAD tokens here (Using msg.value mock for MVP)
        require(msg.value == amount * 1 ether, "Incorrect payment");

        marketSize[battleId][optionType] += amount;

        uint256 expectedTokenId = getOptionId(battleId, optionType);
        _mint(msg.sender, expectedTokenId, amount, "");

        emit OptionsMinted(msg.sender, battleId, optionType, amount);
    }

    /**
     * @notice Called by the HuntingGrounds contract after the N-round Polya Urn finishes.
     * @param battleId The resolved battle
     * @param finalRed The final number of Red balls in the Urn
     * @param finalBlue The final number of Blue balls in the Urn
     */
    function resolveMarket(uint256 battleId, uint256 finalRed, uint256 finalBlue) external onlyHuntingGrounds {
        require(!marketResolved[battleId], "Already resolved");

        marketResolved[battleId] = true;

        if (finalRed > finalBlue) {
            winningOptionId[battleId] = 0; // Red Heavy wins
        } else {
            winningOptionId[battleId] = 1; // Blue Heavy wins
        }
    }

    /**
     * @notice Exercise winning options to claim a share of the loser's locked tokens.
     */
    function exerciseOption(uint256 battleId) external nonReentrant {
        require(marketResolved[battleId], "Market not resolved");

        uint256 winnerId = winningOptionId[battleId];
        uint256 loserId = winnerId == 0 ? 1 : 0;

        uint256 winningTokenId = getOptionId(battleId, winnerId);
        uint256 userBalance = balanceOf(msg.sender, winningTokenId);

        require(userBalance > 0, "No winning tokens");

        uint256 winnerPool = marketSize[battleId][winnerId];
        require(winnerPool > 0, "No winning distribution"); // Protects against Division by Zero

        uint256 loserPool = marketSize[battleId][loserId];
        uint256 totalPool = winnerPool + loserPool;

        // Calculate payout proportion
        uint256 payout = (userBalance * totalPool) / winnerPool;

        // Burn the option token
        _burn(msg.sender, winningTokenId, userBalance);

        // Payout the DREAD (using ether for MVP mock)
        (bool success, ) = payable(msg.sender).call{value: payout}("");
        require(success, "Transfer failed");

        emit OptionsExercised(msg.sender, battleId, payout);
    }
}

